/**
 * Milestone rows, the open-count the cap reads, and the per-milestone progress counters over live issues.
 *
 * Must call (do not reimplement): orgPredicate, toMilestone, milestoneNameKey, CLOSED_ISSUE_STATUSES
 */
import { and, count, eq, inArray, isNotNull, isNull, notInArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of one project, closed ones included, in no particular order. */
export async function listMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all();
  return rows.map(toMilestone);
}

/** Open milestones only; the per-project cap reads this. */
export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      nameKey: milestoneNameKey(input.name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

/** Only the fields the caller supplied are written; `undefined` means "keep". */
export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined
        ? {}
        : { name: patch.name, nameKey: milestoneNameKey(patch.name) }),
      ...(patch.targetDate === undefined ? {} : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/** Reopen passes `null`; the close path goes through `closeMilestoneMovingIssues`. */
export async function setMilestoneClosedAt(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp | null,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Counts live issues per milestone in one grouped query, so a list of any
 * length costs a single round trip. A milestone with no live issues is absent
 * from the map; callers read that as zero.
 */
export async function progressByMilestone(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const progress = new Map<MilestoneId, { total: number; open: number; closed: number }>();
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.milestoneId, [...milestoneIds]),
        isNull(issues.archivedAt),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  const closedStatuses: readonly string[] = CLOSED_ISSUE_STATUSES;
  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const id = row.milestoneId as MilestoneId;
    const entry = progress.get(id) ?? { total: 0, open: 0, closed: 0 };
    entry.total += row.value;
    if (closedStatuses.includes(row.status)) {
      entry.closed += row.value;
    } else {
      entry.open += row.value;
    }
    progress.set(id, entry);
  }

  return progress;
}

/**
 * Closes a milestone and moves its open live issues in one transaction.
 * Returns the moved issues with their assignees, read inside the same
 * transaction so the alert fan-out sees exactly what moved.
 */
export async function closeMilestoneMovingIssues(input: {
  orgId: OrgId;
  milestoneId: MilestoneId;
  movedToMilestoneId: MilestoneId | null;
  closedAt: IsoTimestamp;
}): Promise<readonly { issueId: IssueId; assigneeId: UserId | null }[]> {
  const { orgId, milestoneId, movedToMilestoneId, closedAt } = input;

  return getDb().transaction((tx) => {
    const open = tx
      .select({ issueId: issues.id, assigneeId: issues.assigneeId })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
          notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
        ),
      )
      .all();

    if (open.length > 0) {
      tx.update(issues)
        .set({ milestoneId: movedToMilestoneId, updatedAt: closedAt })
        .where(
          and(
            orgPredicate(issues.orgId, orgId),
            inArray(
              issues.id,
              open.map((row) => row.issueId),
            ),
          ),
        )
        .run();
    }

    tx.update(milestones)
      .set({ closedAt, updatedAt: closedAt })
      .where(
        and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
      )
      .run();

    return open.map((row) => ({
      issueId: row.issueId as IssueId,
      assigneeId: row.assigneeId === null ? null : (row.assigneeId as UserId),
    }));
  });
}

