 * are not significant, so `" Beta "` and `"beta"` collide.
 */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * Open, dated in the past, and still holding open issues. A milestone without
 * a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): boolean {
  if (milestone.closedAt !== null || milestone.targetDate === null) return false;
  return Date.parse(milestone.targetDate) < now.getTime() && progress.open > 0;
}

/**
 * Listing order: open before closed; then earliest target date first, with
 * undated milestones last; then oldest creation first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const closedOrder = Number(a.closedAt !== null) - Number(b.closedAt !== null);
  if (closedOrder !== 0) return closedOrder;

  if (a.targetDate === null || b.targetDate === null) {
    if (a.targetDate !== b.targetDate) return a.targetDate === null ? 1 : -1;
  } else {
    const byTarget = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (byTarget !== 0) return byTarget;
  }

  const byCreation = Date.parse(a.createdAt) - Date.parse(b.createdAt);
  if (byCreation !== 0) return byCreation;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

