/**
 * Milestone rules that do not need a repository: the state-conflict error the
 * service layer throws and the name normalisation that makes names unique.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const REASON_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: "The project already has the maximum number of open milestones.",
  name_taken: "A milestone with this name already exists in the project.",
};

/**
 * A milestone operation that conflicts with the milestone's current state.
 * `toAppError` maps it to `conflict`; `isDomainError` recognises it.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(REASON_MESSAGES[reason]);
    this.name = "MilestoneStateError";
  }
}

/**
 * The uniqueness key for a milestone name: surrounding spaces and letter case
 * are not significant, so `" Beta "` and `"beta"` collide.
 */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

