    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and retargets. Allowed whether the milestone is open or closed. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const { milestone } = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const name = input.name === undefined ? undefined : input.name.trim();
  if (name !== undefined) {
    await assertNameAvailable(input.orgId, milestone.projectId, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    ...(name === undefined ? {} : { name }),
    ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
  });
}

/**
 * Closes an open milestone. Its open live issues move to `moveOpenIssuesTo`
 * (another open milestone of the same project) or, when that is null, out of
 * any milestone. Closed and archived issues stay where they are.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const { milestone } = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");

  const target =
    input.moveOpenIssuesTo === null
      ? null
      : await requireCloseTarget(input.orgId, milestone, input.moveOpenIssuesTo);

  const moved = await milestoneRepo.closeMilestoneMovingIssues({
    orgId: input.orgId,
    milestoneId: milestone.id,
    movedToMilestoneId: target?.id ?? null,
    closedAt: toIsoTimestamp(new Date()),
  });
  const movedIssueIds = moved.map((issue) => issue.issueId);

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
    movedToMilestoneId: target?.id ?? null,
    movedIssueIds,
  });

  const closed = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, milestone.id),
    "Milestone",
    milestone.id,
  );
  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const { milestone } = await loadMilestoneForWrite(actor, orgId, milestoneId);
  if (milestone.closedAt === null) throw new MilestoneStateError("already_open");

  await assertRoomForOpenMilestone(orgId, milestone.projectId);
  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open milestones first, then closed; each group by target date, earliest first. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [...(await milestoneRepo.listMilestones(orgId, projectId))].sort(
    compareMilestones,
  );
  const progress = await milestoneRepo.progressByMilestone(
    orgId,
    milestones.map((milestone) => milestone.id),
  );

  const now = new Date();
  return milestones.map((milestone) =>
    withProgress(milestone, progress.get(milestone.id), now),
  );
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.progressByMilestone(orgId, [milestone.id]);
  return withProgress(milestone, progress.get(milestone.id), new Date());
}

/**
 * The check an issue create or move runs on its target milestone: the
 * milestone must belong to the issue's own project and must be open. Other
 * projects and other workspaces both read as not found.
 */
export async function requireOpenMilestoneForIssue(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

/** The project a milestone write lands in, after the permission and archive guards. */
async function loadProjectForWrite(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function loadMilestoneForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadProjectForWrite(actor, orgId, milestone.projectId);
  return { milestone, project };
}

/**
 * The close target must be another open milestone of the same project. The
 * milestone itself reads as not found, as does one from another project.
 */
async function requireCloseTarget(
  orgId: OrgId,
  closing: Milestone,
  targetId: MilestoneId,
): Promise<Milestone> {
  if (targetId === closing.id) throw new NotFoundError("Milestone", targetId);

  const target = requireFound(
    await milestoneRepo.findMilestoneById(orgId, targetId),
    "Milestone",
    targetId,
  );
  if (target.projectId !== closing.projectId) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) throw new MilestoneStateError("closed");
  return target;
}

/** Names are unique per project, letter case and surrounding spaces aside, closed milestones included. */
async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptMilestoneId: MilestoneId | null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const taken = (await milestoneRepo.listMilestones(orgId, projectId)).some(
    (milestone) =>
      milestone.id !== exceptMilestoneId &&
      milestoneNameKey(milestone.name) === key,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

async function assertRoomForOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress | undefined,
  now: Date,
): MilestoneWithProgress {
  const counts = progress ?? { total: 0, open: 0, closed: 0 };
  return {
    milestone,
    progress: counts,
    overdue: isMilestoneOverdue(milestone, counts, now),
  };
}

