export * as invitationService from "./invitation-service";
export * as issueService from "./issue-service";
export * as labelService from "./label-service";
export * as memberService from "./member-service";
export * as notificationService from "./notification-service";
export * as organizationService from "./organization-service";
export * as projectService from "./project-service";
export * as searchService from "./search-service";
export * as sessionService from "./session-service";
export * as usageService from "./usage-service";
export * as webhookService from "./webhook-service";

export {
  registerEventHandlers,
  unregisterEventHandlers,
} from "./event-registry";

export type { ActivityRecordInput } from "./activity-service";
export type {
  EmailTemplate,
  OutgoingEmail,
  RenderedEmail,
} from "./email-service";
export type { NotificationPayload } from "./notification-service";
export type { SearchHit } from "./search-service";

/**
 * Barrel for the data-access layer.
 *
 * Services import the namespace they need (`import * as issueRepo from
 * "@/server/repositories/issue-repository"`) — this barrel exists for the few
 * call sites that touch several tables at once, and to give the layer one
 * documented entry point. Nothing outside `src/server/**` may import it: the
 * app and component layers go through `src/server/services`.
 */
export * as activityRepository from "./activity-repository";
export * as attachmentRepository from "./attachment-repository";
export * as commentRepository from "./comment-repository";
export * as invitationRepository from "./invitation-repository";
export * as invoiceRepository from "./invoice-repository";
