    userId: user.id,
    role: "member",
    status: "active",
    invitedBy: null,
    joinedAt: EPOCH,
    lastSeenAt: EPOCH,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
    user,
  };
}

export function makeLimitCheck(overrides: Partial<LimitCheck> = {}): LimitCheck {
  const limit = overrides.limit ?? 3;
  const used = overrides.used ?? 1;
  return {
    resource: "seats",
    plan: "free",
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: used >= limit,
    ...overrides,
  };
}

import { describe, expect, it } from "vitest";
import {
  buildBoardColumns,
  compareBoardIssues,
  findIssue,
  moveIssueInColumns,
  orderColumns,
} from "@/components/domain/board/board-model";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

const ORG_ID = "org_1" as OrgId;
const PROJECT_ID = "prj_1" as ProjectId;
const AUTHOR_ID = "usr_1" as UserId;

function issue(
  id: string,
  status: IssueStatus,
  priority: IssuePriority = "none",
  createdAt = "2026-01-01T00:00:00.000Z",
): Issue {
  return {
    id: id as IssueId,
    orgId: ORG_ID,
    projectId: PROJECT_ID,
    number: Number(id.replace(/\D/g, "")) || 1,
    title: `Issue ${id}`,
    description: null,
    status,
    priority,
    authorId: AUTHOR_ID,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: toIsoTimestamp(createdAt),
    updatedAt: toIsoTimestamp(createdAt),
  };
}

describe("board-model/buildBoardColumns", () => {
  it("creates one column per status in workflow order", () => {
    const columns = buildBoardColumns([issue("i1", "todo")]);
    expect(columns.map((column) => column.status)).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
      "done",
      "canceled",
    ]);
  });

  it("counts each column and keeps empty ones", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo"),
      issue("i2", "todo"),
      issue("i3", "done"),
    ]);
    const byStatus = new Map(columns.map((c) => [c.status, c]));
    expect(byStatus.get("todo")?.total).toBe(2);
    expect(byStatus.get("done")?.total).toBe(1);
    expect(byStatus.get("backlog")?.issues).toEqual([]);
  });

  it("orders a column by priority first, then age", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo", "low", "2026-01-01T00:00:00.000Z"),
      issue("i2", "todo", "urgent", "2026-02-01T00:00:00.000Z"),
      issue("i3", "todo", "low", "2025-12-01T00:00:00.000Z"),
    ]);
    const todo = columns.find((column) => column.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i3", "i1"]);
  });
});

describe("board-model/compareBoardIssues", () => {
  it("ranks urgent above high", () => {
    expect(
      compareBoardIssues(issue("a", "todo", "urgent"), issue("b", "todo", "high")),
    ).toBeLessThan(0);
  });
});

describe("board-model/moveIssueInColumns", () => {
  const columns = buildBoardColumns([
    issue("i1", "todo"),
    issue("i2", "todo"),
    issue("i3", "in_progress"),
  ]);

  it("moves an issue between columns and rewrites its status", () => {
    const next = moveIssueInColumns(columns, "i1" as IssueId, "in_progress", 0);
    const todo = next.find((c) => c.status === "todo");
    const inProgress = next.find((c) => c.status === "in_progress");

    expect(todo?.issues.map((i) => i.id)).toEqual(["i2"]);
    expect(todo?.total).toBe(1);
    expect(inProgress?.issues.map((i) => i.id)).toEqual(["i1", "i3"]);
    expect(findIssue(next, "i1" as IssueId)?.status).toBe("in_progress");
  });

  it("clamps an index past the end of the target column", () => {
    const next = moveIssueInColumns(columns, "i3" as IssueId, "todo", 99);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i1", "i2", "i3"]);
  });

  it("re-orders within the same column without duplicating the card", () => {
    const next = moveIssueInColumns(columns, "i2" as IssueId, "todo", 0);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i1"]);
    expect(todo?.total).toBe(2);
  });

  it("leaves the board untouched for an unknown issue", () => {
    expect(moveIssueInColumns(columns, "nope" as IssueId, "done", 0)).toBe(
      columns,
    );
  });
});

describe("board-model/orderColumns", () => {
  it("restores workflow order from an arbitrary arrangement", () => {
    const scrambled = [
      { status: "done" as IssueStatus, issues: [], total: 0 },
      { status: "backlog" as IssueStatus, issues: [], total: 0 },
    ];
    expect(orderColumns(scrambled).map((c) => c.status)).toEqual([
      "backlog",
      "done",
    ]);
  });
});

import { describe, expect, it } from "vitest";
import {
  isClosedStatus,
  optimisticIssuesReducer,
  withAssignee,
  withStatus,
} from "@/hooks/optimistic-issues-reducer";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

const AT = toIsoTimestamp("2026-03-01T12:00:00.000Z");

const BASE: Issue = {
  id: "iss_1" as IssueId,
  orgId: "org_1" as OrgId,
  projectId: "prj_1" as ProjectId,
  number: 12,
  title: "Fix the thing",
  description: null,
  status: "todo",
  priority: "medium",
  authorId: "usr_1" as UserId,
  assigneeId: null,
  parentId: null,
  estimate: null,
  dueAt: null,
  startedAt: null,
  completedAt: null,
  labelIds: [],
  archivedAt: null,
  createdAt: toIsoTimestamp("2026-01-01T00:00:00.000Z"),
  updatedAt: toIsoTimestamp("2026-01-01T00:00:00.000Z"),
};

describe("optimistic-issues/isClosedStatus", () => {
  it("treats done and canceled as closed", () => {
    expect(isClosedStatus("done")).toBe(true);
    expect(isClosedStatus("canceled")).toBe(true);
    expect(isClosedStatus("in_review")).toBe(false);
  });
});

describe("optimistic-issues/withStatus", () => {
  it("stamps completedAt when the issue closes", () => {
    const next = withStatus(BASE, "done", AT);
    expect(next.status).toBe("done");
    expect(next.completedAt).toBe(AT);
    expect(next.updatedAt).toBe(AT);
  });

  it("clears completedAt when the issue is reopened", () => {
    const closed = withStatus(BASE, "done", AT);
    const reopened = withStatus(closed, "in_progress", AT);
    expect(reopened.completedAt).toBeNull();
  });

  it("stamps startedAt the first time work begins", () => {
    const started = withStatus(BASE, "in_progress", AT);
    expect(started.startedAt).toBe(AT);

    const later = toIsoTimestamp("2026-04-01T00:00:00.000Z");
    const paused = withStatus(started, "todo", later);
    const resumed = withStatus(paused, "in_progress", later);
    expect(resumed.startedAt).toBe(AT);
  });

  it("is a no-op when the status is unchanged", () => {
    expect(withStatus(BASE, "todo", AT)).toBe(BASE);
  });
});

describe("optimistic-issues/withAssignee", () => {
  it("assigns and touches updatedAt", () => {
    const next = withAssignee(BASE, "usr_2" as UserId, AT);
    expect(next.assigneeId).toBe("usr_2");
    expect(next.updatedAt).toBe(AT);
  });

  it("is a no-op when the assignee is unchanged", () => {
    expect(withAssignee(BASE, null, AT)).toBe(BASE);
  });
});

describe("optimistic-issues/reducer", () => {
  const issues = [BASE, { ...BASE, id: "iss_2" as IssueId, number: 13 }];

  it("only rewrites the targeted issue", () => {
    const next = optimisticIssuesReducer(issues, {
      kind: "status",
      issueId: "iss_2" as IssueId,
      status: "done",
    });
    expect(next[0]).toBe(issues[0]);
    expect(next[1]?.status).toBe("done");
  });

  it("applies an assignee change", () => {
    const next = optimisticIssuesReducer(issues, {
      kind: "assignee",
      issueId: "iss_1" as IssueId,
      assigneeId: "usr_9" as UserId,
    });
    expect(next[0]?.assigneeId).toBe("usr_9");
  });

  it("leaves the list alone for an unknown id", () => {
    const next = optimisticIssuesReducer(issues, {
      kind: "status",
      issueId: "missing" as IssueId,
      status: "done",
    });
    expect(next).toEqual(issues);
  });
});

