  });

  it("counts progress over live issues and flags only open, past-dated milestones with open work as overdue", async () => {
    const projectId = await newProject("progress", "PRG");
    const issueIn = (milestoneId: MilestoneId, title: string) =>
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, projectId, { title }),
        milestoneId,
      });

    const late = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Late", "2020-01-01T00:00:00.000Z", projectId),
    });
    const finished = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Finished", "2020-02-01T00:00:00.000Z", projectId),
    });
    const undatedWork = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Undated work", null, projectId),
    });

    const openOne = await issueIn(late.id, "Open one");
    await issueIn(late.id, "Open two");
    const doneOne = await issueIn(late.id, "Done one");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneOne.id,
      status: "done",
    });
    const archivedOne = await issueIn(late.id, "Archived one");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedOne.id);

    const finishedIssue = await issueIn(finished.id, "Finished issue");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: finishedIssue.id,
      status: "canceled",
    });
    await issueIn(undatedWork.id, "Undated open");

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );
    const byName = new Map(listed.map((entry) => [entry.milestone.name, entry]));

    expect(byName.get("Late")).toMatchObject({
      progress: { total: 3, open: 2, closed: 1 },
      overdue: true,
    });
    expect(byName.get("Finished")).toMatchObject({
      progress: { total: 1, open: 0, closed: 1 },
      overdue: false,
    });
    expect(byName.get("Undated work")).toMatchObject({
      progress: { total: 1, open: 1, closed: 0 },
      overdue: false,
    });

    const single = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      late.id,
