    expect(result.milestone.closedAt).not.toBeNull();
    expect([...result.movedIssueIds].sort()).toEqual(
      [toAdmin.id, ownedByCloser.id, unassigned.id].sort(),
    );

    expect(seen).toEqual([
      expect.objectContaining({
        milestoneId: source.id,
        movedToMilestoneId: target.id,
        movedIssueIds: result.movedIssueIds,
      }),
    ]);

    const moved = await issueRepo.findIssueById(tenant.org.id, toAdmin.id);
    expect(moved?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, done.id))?.milestoneId).toBe(
      source.id,
    );
    expect((await issueRepo.findIssueById(tenant.org.id, archived.id))?.milestoneId).toBe(
      source.id,
    );

    expect(await alertsFor(tenant.userIds.admin)).toHaveLength(1);
    expect(await alertsFor(tenant.userIds.owner)).toHaveLength(0);
  });

  it("takes open issues out of any milestone when no target is named", async () => {
    const source = await createMilestone("Loose ends");
    const issue = await issueWith(source.id, { assigneeId: tenant.userIds.viewer });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
    });

    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBeNull();
    expect(await alertsFor(tenant.userIds.viewer)).toHaveLength(1);
  });

  it("refuses a closed target, a target that is the milestone itself, and a target from another project, changing nothing", async () => {
    const source = await createMilestone("Guarded source");
    const closedTarget = await createMilestone("Guarded closed target");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput("Guarded foreign", null, secondProjectId),
    );
    const issue = await issueWith(source.id);
    const seen = capture("milestone.closed");

    await expectStateError(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: closedTarget.id,
      }),
      "closed",
    );
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(seen).toHaveLength(0);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBe(
      source.id,
    );
    expect((await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, source.id))
      .milestone.closedAt).toBeNull();
  });

  it("refuses to close a milestone that is already closed", async () => {
    const milestone = await createMilestone("Twice");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    await expectStateError(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      }),
      "closed",
    );
  });
});

describe("services/milestone-service: list and get", () => {
  it("lists open milestones first, by target date with undated last, then closed ones", async () => {
    const projectId = await newProject("ordering", "ORD");
    const create = (name: string, targetDate: string | null) =>
      milestoneService.createMilestone(
        tenant.actors.member,
        milestoneInput(name, targetDate, projectId),
      );

    const later = await create("Later", "2031-06-01T00:00:00.000Z");
    const undated = await create("Undated", null);
    const sooner = await create("Sooner", "2031-01-01T00:00:00.000Z");
    const retired = await create("Retired", "2029-01-01T00:00:00.000Z");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: retired.id,
      moveOpenIssuesTo: null,
    });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );

    expect(listed.map((entry) => entry.milestone.id)).toEqual([
      sooner.id,
      later.id,
      undated.id,
      retired.id,
    ]);
  });

  it("counts progress over live issues and flags only open, past-dated milestones with open work as overdue", async () => {
    const projectId = await newProject("progress", "PRG");
    const issueIn = (milestoneId: MilestoneId, title: string) =>
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, projectId, { title }),
        milestoneId,
      });

    const late = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Late", "2020-01-01T00:00:00.000Z", projectId),
    });
    const finished = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Finished", "2020-02-01T00:00:00.000Z", projectId),
    });
    const undatedWork = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Undated work", null, projectId),
    });

    const openOne = await issueIn(late.id, "Open one");
    await issueIn(late.id, "Open two");
    const doneOne = await issueIn(late.id, "Done one");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneOne.id,
      status: "done",
    });
    const archivedOne = await issueIn(late.id, "Archived one");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedOne.id);

    const finishedIssue = await issueIn(finished.id, "Finished issue");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: finishedIssue.id,
      status: "canceled",
    });
    await issueIn(undatedWork.id, "Undated open");

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );
    const byName = new Map(listed.map((entry) => [entry.milestone.name, entry]));

    expect(byName.get("Late")).toMatchObject({
      progress: { total: 3, open: 2, closed: 1 },
      overdue: true,
    });
    expect(byName.get("Finished")).toMatchObject({
      progress: { total: 1, open: 0, closed: 1 },
      overdue: false,
    });
    expect(byName.get("Undated work")).toMatchObject({
      progress: { total: 1, open: 1, closed: 0 },
      overdue: false,
    });

    const single = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      late.id,
    );
    expect(single.progress).toEqual({ total: 3, open: 2, closed: 1 });
    expect(openOne.milestoneId).toBe(late.id);
  });

  it("refuses to list a project the actor may not read through another workspace", async () => {
    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service: milestone membership", () => {
  it("moves an issue into an open milestone, to another, and out again", async () => {
    const first = await createMilestone("Move first");
    const second = await createMilestone("Move second");
    const issue = await issueWith(null);

    const inFirst = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: first.id,
    });
    expect(inFirst.milestoneId).toBe(first.id);

    const inSecond = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: second.id,
    });
    expect(inSecond.milestoneId).toBe(second.id);

    const out = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(out.milestoneId).toBeNull();
  });

  it("refuses a closed milestone, one from another project, a viewer, and an archived issue", async () => {
    const closed = await createMilestone("Move closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput("Move foreign", null, secondProjectId),
    );
    const issue = await issueWith(null);

    await expectStateError(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: closed.id,
      }),
      "closed",
    );
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const open = await createMilestone("Move archived");
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: open.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a milestone at creation and creates nothing", async () => {
    const closed = await createMilestone("Create closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const seen = capture("issue.created");

    await expectStateError(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Never created" }),
        milestoneId: closed.id,
      }),
      "closed",
    );

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
    expect(seen).toHaveLength(0);
  });
});

describe("services/milestone-service: audit", () => {
  it("records created, closed and reopened milestones against the milestone subject", async () => {
    const off = registerActivityListeners();
    try {
      const milestone = await createMilestone("Audited");
      await milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      });
      await milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id);

      const page = await activityService.listActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        subjectKind: "milestone",
        limit: 100,
        cursor: null,
      });
      const actions = page.items
        .filter((event) => event.subjectId === milestone.id)
        .map((event) => event.action)
        .sort();

      expect(actions).toEqual(["milestone.closed", "milestone.created", "milestone.reopened"]);
      expect(page.items.every((event) => event.projectId === tenant.project.id)).toBe(true);
    } finally {
      off();
    }
  });
});

