/**
 * Milestone rules: create / rename / close / reopen guards, the open cap, listing order, progress and overdue, and issue moves into and out of milestones.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import type { MilestoneStateReason } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as activityService from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CreateMilestoneInput } from "@/schemas/milestone";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, MilestoneId, ProjectId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let secondProjectId: ProjectId;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Resolves to the rejection reason, so state errors can be inspected. */
async function rejectionOf(promise: Promise<unknown>): Promise<unknown> {
  return promise.then(
    () => {
      throw new Error("expected the call to be refused");
    },
    (error: unknown) => error,
  );
}

async function expectStateError(
  promise: Promise<unknown>,
  reason: MilestoneStateReason,
): Promise<void> {
  const error = await rejectionOf(promise);
  expect(error).toBeInstanceOf(MilestoneStateError);
  expect((error as MilestoneStateError).reason).toBe(reason);
}

function milestoneInput(
  name: string,
  targetDate: string | null = null,
  projectId: ProjectId = tenant.project.id,
): CreateMilestoneInput {
  return {
    orgId: tenant.org.id,
    projectId,
    name,
    targetDate: targetDate === null ? null : toIsoTimestamp(targetDate),
  };
}

function createMilestone(name: string, targetDate: string | null = null) {
  return milestoneService.createMilestone(
    tenant.actors.member,
    milestoneInput(name, targetDate),
  );
}

async function newProject(slug: string, key: string): Promise<ProjectId> {
  const project = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: `${slug} project`,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

function issueWith(
  milestoneId: MilestoneId | null,
  overrides: { assigneeId?: UserId | null; title?: string } = {},
) {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title: overrides.title ?? "Milestone work",
      assigneeId: overrides.assigneeId ?? null,
    }),
    milestoneId,
  });
}

async function alertsFor(recipient: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: ["issue_milestone_changed"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones");
  other = await createTenant("elsewhere");
  secondProjectId = await newProject("second", "SEC");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("services/milestone-service: create", () => {
  it("opens a milestone and announces it once", async () => {
    const seen = capture("milestone.created");

    const milestone = await createMilestone("Launch");

    expect(milestone).toMatchObject({
      name: "Launch",
      projectId: tenant.project.id,
      targetDate: null,
      closedAt: null,
    });
    expect(seen).toEqual([
      expect.objectContaining({
        milestoneId: milestone.id,
        projectId: tenant.project.id,
        actorId: tenant.userIds.member,
      }),
    ]);
  });

  it("refuses a viewer, who may not edit the project", async () => {
    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, milestoneInput("Nope")),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an organization outside the actor's workspace", async () => {
    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        ...milestoneInput("Elsewhere"),
        orgId: other.org.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("reads another workspace's project as not found", async () => {
    await expect(
      milestoneService.createMilestone(
        tenant.actors.member,
        milestoneInput("Foreign", null, other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a name taken without regard to case or surrounding spaces, closed milestones included", async () => {
    const beta = await createMilestone("Beta");
    await expectStateError(createMilestone("  beta "), "name_taken");

    await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: beta.id,
      moveOpenIssuesTo: null,
    });
    await expectStateError(createMilestone("BETA"), "name_taken");
  });

  it("allows the same name in another project", async () => {
    await createMilestone("Gamma");
    const milestone = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput("Gamma", null, secondProjectId),
    );
    expect(milestone.projectId).toBe(secondProjectId);
  });

  it("caps open milestones per project, and closing one frees a slot", async () => {
    const capped = await newProject("capped", "CAP");
    const opened = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      opened.push(
        await milestoneService.createMilestone(
          tenant.actors.member,
          milestoneInput(`Cap ${i}`, null, capped),
        ),
      );
    }

    await expectStateError(
      milestoneService.createMilestone(
        tenant.actors.member,
        milestoneInput("Overflow", null, capped),
      ),
      "too_many_open",
    );

    const first = opened[0];
    if (first === undefined) throw new Error("setup failed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.createMilestone(
        tenant.actors.member,
        milestoneInput("Overflow", null, capped),
      ),
    ).resolves.toMatchObject({ name: "Overflow" });

    await expectStateError(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, first.id),
      "too_many_open",
    );
  });
});

describe("services/milestone-service: update and reopen", () => {
  it("renames and retargets, keeping the name unique within the project", async () => {
    const one = await createMilestone("Rename me");
    await createMilestone("Taken name");

    const renamed = await milestoneService.updateMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: one.id,
      name: "RENAMED",
      targetDate: toIsoTimestamp("2031-02-01T00:00:00.000Z"),
    });
    expect(renamed).toMatchObject({
      name: "RENAMED",
      targetDate: "2031-02-01T00:00:00.000Z",
    });

    await expectStateError(
      milestoneService.updateMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: one.id,
        name: " taken NAME ",
      }),
      "name_taken",
    );
  });

  it("refuses to reopen an open milestone, and reopens a closed one with an announcement", async () => {
    const milestone = await createMilestone("Reopen me");
    await expectStateError(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id),
      "already_open",
    );

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });
    const seen = capture("milestone.reopened");

    const reopened = await milestoneService.reopenMilestone(
      tenant.actors.member,
      tenant.org.id,
      milestone.id,
    );

    expect(reopened.closedAt).toBeNull();
    expect(seen).toEqual([
      expect.objectContaining({ milestoneId: milestone.id, projectId: tenant.project.id }),
    ]);
  });
});

describe("services/milestone-service: close", () => {
  it("moves open issues to the named milestone, leaves closed and archived ones behind, and alerts each assignee once", async () => {
    const source = await createMilestone("Source", "2031-03-01T00:00:00.000Z");
    const target = await createMilestone("Target", "2031-04-01T00:00:00.000Z");

    const toAdmin = await issueWith(source.id, { assigneeId: tenant.userIds.admin });
    const ownedByCloser = await issueWith(source.id, { assigneeId: tenant.userIds.owner });
    const unassigned = await issueWith(source.id);
    const done = await issueWith(source.id);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: done.id,
      status: "done",
    });
    const archived = await issueWith(source.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const seen = capture("milestone.closed");

    const result = await milestoneService.closeMilestone(tenant.actors.owner, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });

    expect(result.milestone.closedAt).not.toBeNull();
    expect([...result.movedIssueIds].sort()).toEqual(
      [toAdmin.id, ownedByCloser.id, unassigned.id].sort(),
    );

    expect(seen).toEqual([
      expect.objectContaining({
        milestoneId: source.id,
        movedToMilestoneId: target.id,
        movedIssueIds: result.movedIssueIds,
      }),
    ]);

    const moved = await issueRepo.findIssueById(tenant.org.id, toAdmin.id);
    expect(moved?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, done.id))?.milestoneId).toBe(
      source.id,
    );
    expect((await issueRepo.findIssueById(tenant.org.id, archived.id))?.milestoneId).toBe(
      source.id,
    );

    expect(await alertsFor(tenant.userIds.admin)).toHaveLength(1);
    expect(await alertsFor(tenant.userIds.owner)).toHaveLength(0);
  });

  it("takes open issues out of any milestone when no target is named", async () => {
    const source = await createMilestone("Loose ends");
    const issue = await issueWith(source.id, { assigneeId: tenant.userIds.viewer });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
    });

    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBeNull();
    expect(await alertsFor(tenant.userIds.viewer)).toHaveLength(1);
  });

  it("refuses a closed target, a target that is the milestone itself, and a target from another project, changing nothing", async () => {
    const source = await createMilestone("Guarded source");
    const closedTarget = await createMilestone("Guarded closed target");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput("Guarded foreign", null, secondProjectId),
    );
    const issue = await issueWith(source.id);
    const seen = capture("milestone.closed");

    await expectStateError(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: closedTarget.id,
      }),
      "closed",
    );
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(seen).toHaveLength(0);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBe(
      source.id,
    );
    expect((await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, source.id))
      .milestone.closedAt).toBeNull();
  });

  it("refuses to close a milestone that is already closed", async () => {
    const milestone = await createMilestone("Twice");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    await expectStateError(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      }),
      "closed",
    );
  });
});

describe("services/milestone-service: list and get", () => {
  it("lists open milestones first, by target date with undated last, then closed ones", async () => {
    const projectId = await newProject("ordering", "ORD");
    const create = (name: string, targetDate: string | null) =>
      milestoneService.createMilestone(
        tenant.actors.member,
        milestoneInput(name, targetDate, projectId),
      );

    const later = await create("Later", "2031-06-01T00:00:00.000Z");
    const undated = await create("Undated", null);
    const sooner = await create("Sooner", "2031-01-01T00:00:00.000Z");
    const retired = await create("Retired", "2029-01-01T00:00:00.000Z");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: retired.id,
      moveOpenIssuesTo: null,
    });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );

    expect(listed.map((entry) => entry.milestone.id)).toEqual([
      sooner.id,
      later.id,
      undated.id,
      retired.id,
    ]);
  });

  it("counts progress over live issues and flags only open, past-dated milestones with open work as overdue", async () => {
    const projectId = await newProject("progress", "PRG");
    const issueIn = (milestoneId: MilestoneId, title: string) =>
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, projectId, { title }),
        milestoneId,
      });

    const late = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Late", "2020-01-01T00:00:00.000Z", projectId),
    });
    const finished = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Finished", "2020-02-01T00:00:00.000Z", projectId),
    });
    const undatedWork = await milestoneService.createMilestone(tenant.actors.member, {
      ...milestoneInput("Undated work", null, projectId),
    });

    const openOne = await issueIn(late.id, "Open one");
    await issueIn(late.id, "Open two");
    const doneOne = await issueIn(late.id, "Done one");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneOne.id,
      status: "done",
    });
    const archivedOne = await issueIn(late.id, "Archived one");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedOne.id);

    const finishedIssue = await issueIn(finished.id, "Finished issue");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: finishedIssue.id,
      status: "canceled",
    });
    await issueIn(undatedWork.id, "Undated open");

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );
    const byName = new Map(listed.map((entry) => [entry.milestone.name, entry]));

    expect(byName.get("Late")).toMatchObject({
      progress: { total: 3, open: 2, closed: 1 },
      overdue: true,
    });
    expect(byName.get("Finished")).toMatchObject({
      progress: { total: 1, open: 0, closed: 1 },
      overdue: false,
    });
    expect(byName.get("Undated work")).toMatchObject({
      progress: { total: 1, open: 1, closed: 0 },
      overdue: false,
    });

    const single = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      late.id,
    );
    expect(single.progress).toEqual({ total: 3, open: 2, closed: 1 });
    expect(openOne.milestoneId).toBe(late.id);
  });

  it("refuses to list a project the actor may not read through another workspace", async () => {
    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service: milestone membership", () => {
  it("moves an issue into an open milestone, to another, and out again", async () => {
    const first = await createMilestone("Move first");
    const second = await createMilestone("Move second");
    const issue = await issueWith(null);

    const inFirst = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: first.id,
    });
    expect(inFirst.milestoneId).toBe(first.id);

    const inSecond = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: second.id,
    });
    expect(inSecond.milestoneId).toBe(second.id);

    const out = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(out.milestoneId).toBeNull();
  });

  it("refuses a closed milestone, one from another project, a viewer, and an archived issue", async () => {
    const closed = await createMilestone("Move closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput("Move foreign", null, secondProjectId),
    );
    const issue = await issueWith(null);

    await expectStateError(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: closed.id,
      }),
      "closed",
    );
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const open = await createMilestone("Move archived");
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: open.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a milestone at creation and creates nothing", async () => {
    const closed = await createMilestone("Create closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const seen = capture("issue.created");

    await expectStateError(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Never created" }),
        milestoneId: closed.id,
      }),
      "closed",
    );

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
    expect(seen).toHaveLength(0);
  });
});

describe("services/milestone-service: audit", () => {
  it("records created, closed and reopened milestones against the milestone subject", async () => {
    const off = registerActivityListeners();
    try {
      const milestone = await createMilestone("Audited");
      await milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      });
      await milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id);

      const page = await activityService.listActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        subjectKind: "milestone",
        limit: 100,
        cursor: null,
      });
      const actions = page.items
        .filter((event) => event.subjectId === milestone.id)
        .map((event) => event.action)
        .sort();

      expect(actions).toEqual(["milestone.closed", "milestone.created", "milestone.reopened"]);
      expect(page.items.every((event) => event.projectId === tenant.project.id)).toBe(true);
    } finally {
      off();
    }
  });
});

